    completeFinalCheck(new Response(JSON.stringify({ devices: [] }), { status: 200 }));
    await settle();
    const afterFinalAnswer = { cachedIds: [...platform.accessories.keys()], removalStates: [...removalStates] };
    shutdown?.();
