        // arrange
        const marks = [];
        const restored = restoredAccessories();
        const context = discoveryContext({
            api: fakeDiscoveryApi([]),
            accessories: restored.accessories,
            registry: unknownRegistry(),
            basementGuardianAccessories: new Map([[ACCESSORY_UUID, recordingBasementGuardianAccessory(DEVICE_ID, marks)]]),
